  <link href="/app/libs/fonts/inter.css" rel="stylesheet">
  <script src="/app/libs/chart.js"></script>
  <script>Chart.defaults.animation = false;</script>
  <script src="/app/libs/html-to-image.js"></script>
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    :root { interpolate-size: allow-keywords; } /* Enable smooth height:auto transitions (Chrome 129+) */

    /* ===== THEMES (class-based ONLY — no @media prefers-color-scheme) ===== */
    html.theme-dark {
      --bg: #050b14; --surface: #0a1324; --surface-hover: #0f1c35;
      --border: rgba(255,255,255,0.08);
      --text: #F8FAFC; --text-secondary: #94A3B8;
      --accent: #EF4444; --accent-secondary: #F59E0B;
      --positive: #38BDF8; --negative: #991B1B; --warning: #F97316;
    }
    html.theme-light {
      --bg: #F8FAFC; --surface: #FFFFFF; --surface-hover: #F1F5F9;
      --border: rgba(0,0,0,0.1);
      --text: #020617; --text-secondary: #475569;
      --accent: #DC2626; --accent-secondary: #D97706;
      --positive: #0284C7; --negative: #7F1D1D; --warning: #EA580C;
    }

    body {
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
      background: var(--bg); color: var(--text);
      line-height: 1.6; -webkit-font-smoothing: antialiased;
      letter-spacing: -0.01em; font-feature-settings: 'cv11', 'ss01';
      transition: background 0.3s, color 0.3s;
      scrollbar-gutter: stable;

      /* POSTER SPECIFIC DIMENSIONS */
      width: 2160px;
      height: 3054px;
      overflow: hidden;
      display: flex;
      flex-direction: column;
    }
    h1,h2,h3,h4,h5,h6 { 
      color: var(--text); 
      letter-spacing: -0.03em; 
      line-height: 1.08;
      text-wrap: balance;
    }
    h1 { font-weight: 700; }
    h2 { font-weight: 600; }
    body, p, li, td, th, span, label { font-weight: 400; }
    p,li,td,th,span,label { color: var(--text); }
    .text-secondary { color: var(--text-secondary); }

    /* ===== CARD ===== */
    .card {
      background: var(--surface); border: 1px solid var(--border);
      border-radius: 8px; padding: 24px;
      transition: box-shadow 0.2s ease;
    }
    .card:hover {
      box-shadow: 0 0 0 1px var(--border), 0 8px 16px rgba(0,0,0,0.08);
    }

    /* ===== ANIMATIONS (CSS-first — always reliable) ===== */
    @keyframes fadeInUp {
      from { opacity: 0; transform: translateY(24px); }
      to { opacity: 1; transform: translateY(0); }
    }
    @keyframes fadeIn {
      from { opacity: 0; }
      to { opacity: 1; }
    }
    @keyframes slideInLeft {
      from { opacity: 0; transform: translateX(-40px); }
      to { opacity: 1; transform: translateX(0); }
    }
    @keyframes slideInRight {
      from { opacity: 0; transform: translateX(40px); }
      to { opacity: 1; transform: translateX(0); }
    }
    .animate { animation: fadeInUp 0.6s ease-out both; }
    .animate.delay-1 { animation-delay: 0.1s; }
    .animate.delay-2 { animation-delay: 0.2s; }
    .animate.delay-3 { animation-delay: 0.3s; }
    .animate.delay-4 { animation-delay: 0.4s; }
    .animate.delay-5 { animation-delay: 0.5s; }
    .animate.delay-6 { animation-delay: 0.6s; }

    /* Scroll-triggered: JS adds .reveal, then .visible on scroll */
    .reveal { opacity: 0; transform: translateY(24px); transition: opacity 0.6s ease, transform 0.6s ease; }
    .reveal.visible { opacity: 1; transform: translateY(0); }

    @media (prefers-reduced-motion: reduce) {
      *, *::before, *::after { animation: none !important; transition: none !important; }
      .reveal { opacity: 1; transform: none; }
    }

    /* ===== PRINT ===== */
    @media print {
      body { background: white !important; color: black !important; }
      .viz-menu, .reveal { display: revert; opacity: 1 !important; transform: none !important; }
      .card { break-inside: avoid; border: 1px solid #ddd; box-shadow: none; }
      * { print-color-adjust: exact; -webkit-print-color-adjust: exact; }
    }
    @page { margin: 1in; @bottom-center { content: "Page " counter(page); font-size: 9pt; color: #666; } }

    /* ===== MENU ===== */
    .viz-menu { position: fixed; top: 16px; right: 16px; z-index: 9999; }
    .viz-menu-toggle {
      width: 44px; height: 44px; border-radius: 12px;
      background: var(--surface); border: 1px solid var(--border);
      color: var(--text); cursor: pointer; display: flex;
      align-items: center; justify-content: center;
      backdrop-filter: blur(12px); transition: all 0.2s;
    }
    .viz-menu-toggle:hover { background: var(--surface-hover); }
    .viz-menu-dropdown {
      position: absolute; top: 52px; right: 0; min-width: 200px;
      background: var(--surface); border: 1px solid var(--border);
      border-radius: 12px; padding: 8px;
      opacity: 0; visibility: hidden; transform: translateY(-8px);
      transition: all 0.2s; backdrop-filter: blur(16px);
    }
    .viz-menu-dropdown.open { opacity: 1; visibility: visible; transform: translateY(0); }
    .viz-menu-dropdown button {
      width: 100%; padding: 10px 14px; border: none; border-radius: 8px;
      background: transparent; color: var(--text); font-size: 14px;
      font-family: inherit; cursor: pointer; text-align: left;
      display: flex; align-items: center; gap: 10px; transition: background 0.15s;
    }
    .viz-menu-dropdown button:hover { background: var(--surface-hover); }

    /* ===== SKIP TO CONTENT (accessibility) ===== */
    .skip-to-content {
      position: absolute; top: -40px; left: 6px; background: var(--accent);
      color: white; padding: 8px 12px; text-decoration: none;
      border-radius: 4px; opacity: 0; pointer-events: none;
      transition: all 0.2s; z-index: 10000;
    }
    .skip-to-content:focus { top: 6px; opacity: 1; pointer-events: auto; }

    /* ===== DETAILS ACCORDION ===== */
    details { overflow: hidden; }
    details summary { cursor: pointer; list-style: none; }
    details summary::-webkit-details-marker { display: none; }
    ::details-content {
      transition: block-size 0.3s ease, opacity 0.3s ease;
      block-size: 0; opacity: 0; overflow: hidden;
    }
    details[open]::details-content { block-size: auto; opacity: 1; }

    /* ===== POPOVER ===== */
    [popover] {
      background: var(--surface); border: 1px solid var(--border);
      border-radius: 8px; padding: 16px; max-width: 320px;
      box-shadow: 0 8px 32px rgba(0,0,0,0.2); color: var(--text);
    }
    [popover]::backdrop { background: rgba(0,0,0,0.3); }

    /* ===== POSTER SPECIFIC STYLES BELOW ===== */

    h1 { font-weight: 800; font-size: 110px; text-transform: uppercase; letter-spacing: -0.04em; margin-bottom: 16px; }
    h2 { font-weight: 700; font-size: 64px; border-bottom: 2px solid var(--accent); padding-bottom: 16px; margin-bottom: 32px; display: inline-block; line-height: 1.1; }
    h3 { font-weight: 600; font-size: 48px; margin-bottom: 16px; color: var(--accent-secondary); }
    p,li,td,th,span,label { font-size: 32px; }

    .poster-container {
      display: flex;
      flex-direction: column;
      flex: 1;
      padding: 80px 100px;
      justify-content: space-between;
      height: 100%;
    }

    /* Header */
    .poster-header {
      margin-bottom: 60px;
      border-left: 12px solid var(--accent);
      padding-left: 48px;
    }
    .header-subtitle {
...
      display: flex;
      flex-direction: column;
      justify-content: center;
      position: relative;
      overflow: hidden;
      transition: none; /* remove hover for print poster */
    }
    .metric-card::before {
      content: '';
      position: absolute;
      top: 0; left: 0; right: 0;
...
      grid-template-columns: 1fr 1fr;
      gap: 64px;
      flex: 1;
    }

    .poster-column { display: flex; flex-direction: column; gap: 60px; }

    .content-box {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 24px;
      padding: 56px;
      display: flex;
      flex-direction: column;
    }

    ul.custom-list {
      list-style: none;
    }
...
      color: var(--accent);
      font-size: 36px;
    }

    /* Chart Container */
    .chart-container-wrapper {
      height: 550px;
      width: 100%;
      margin-top: 32px;
      padding: 40px;
      border-radius: 12px;
      background: var(--surface);
      border: 1px solid var(--border);
    }
    .chart-container {
      position: relative;
      height: 100%;
      width: 100%;
    }

    /* Narrowing Window / Footer */
    .footer-section {
      margin-top: 40px;
...
      border: 1px solid rgba(255,255,255,0.1);
    }
    .footer-section h2 { border: none; margin-bottom: 24px; padding-bottom: 0; color: white; }
    .footer-section p { font-size: 40px; font-weight: 500; max-width: 1600px; margin: 0 auto; color: rgba(255,255,255,0.9); }

  </style>
</head>
<body>
  <a href="#main-content" class="skip-link" style="position:absolute;left:-9999px;top:auto;width:1px;height:1px;overflow:hidden;z-index:10000;padding:8px 16px;background:var(--accent);color:white;text-decoration:none;border-radius:4px;" onfocus="this.style.cssText='position:fixed;left:16px;top:16px;z-index:10000;padding:8px 16px;background:var(--accent);color:white;text-decoration:none;border-radius:4px;'" onblur="this.style.cssText='position:absolute;left:-9999px;top:auto;width:1px;height:1px;overflow:hidden;'">Skip to content</a>

  <!-- MENU -->
  <div class="viz-menu">
    <button class="viz-menu-toggle" onclick="toggleMenu()" aria-label="Menu">
      <svg width="20" height="20" viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round">
        <line x1="3" y1="5" x2="17" y2="5"/><line x1="3" y1="10" x2="17" y2="10"/><line x1="3" y1="15" x2="17" y2="15"/>
      </svg>
    </button>
    <div class="viz-menu-dropdown" id="vizMenuDropdown">
      <button onclick="cycleTheme()"><span id="themeIcon">🌙</span><span id="themeLabel">Dark</span></button>
      <button onclick="downloadImage()"><span>📥</span><span>Download PNG</span></button>
      <button onclick="window.print()"><span>🖨️</span><span>Print / PDF</span></button>
    </div>
  </div>

  <main id="main-content" role="main" class="poster-container">

    <header class="poster-header animate">
      <h1>Climate Change 2023</h1>
      <div style="font-size: 56px; font-weight: 700; color: var(--accent);">KEY FINDINGS FROM THE IPCC AR6 SYNTHESIS REPORT</div>
      <p class="header-subtitle">A visual summary of the most critical findings from the IPCC AR6 Synthesis Report, highlighting observed changes, future projections, and urgent pathways for climate action.</p>
    </header>

    <section class="metrics-grid animate delay-1">
      <div class="metric-card">
        <div class="metric-value" data-count="1.1" data-prefix="+" data-suffix="°C">1.1°C</div>
        <div class="metric-label">Global surface temp increase<br>(2011–2020 vs 1850–1900)</div>
      </div>
      <div class="metric-card">
        <div class="metric-value" data-count="410" data-suffix=" ppm">410 ppm</div>
        <div class="metric-label">CO₂ concentration in 2019<br>(Highest in 2M years)</div>
      </div>
      <div class="metric-card">
        <div class="metric-value" data-count="59" data-suffix=" Gt">59 Gt</div>
        <div class="metric-label">Global GHG emissions<br>in 2019 (CO₂e)</div>
      </div>
      <div class="metric-card primary">
        <div class="metric-value" data-count="500" data-suffix=" Gt">500 Gt</div>
        <div class="metric-label">Remaining carbon budget<br>for 1.5°C (from 2020)</div>
      </div>
      <div class="metric-card critical" style="grid-column: span 2;">
        <div class="metric-value" data-count="43" data-suffix="%">43%</div>
        <div class="metric-label">Required GHG reduction below 2019 levels by 2030 to limit warming to 1.5°C</div>
      </div>
      <div class="metric-card critical" style="grid-column: span 2;">
        <div class="metric-value">3.3–3.6B</div>
        <div class="metric-label">People currently exposed and highly vulnerable to severe climate hazards</div>
      </div>
    </section>

    <div class="content-grid">
      <!-- Left Column -->
      <div class="poster-column animate delay-2">
        <section class="content-box">
          <h2>Observed Changes & Current State</h2>
          <ul class="custom-list">
            <li><strong>Unprecedented Pace:</strong> Human-caused climate change is affecting every region, driving widespread and rapid changes in atmosphere, ocean, and biosphere.</li>
            <li><strong>Extreme Events:</strong> Increases in frequency and intensity of heatwaves, heavy precipitation, droughts, and tropical cyclones are unequivocally linked to human influence.</li>
...
          </ul>
        </section>
      </div>

      <!-- Right Column -->
      <div class="poster-column animate delay-3">
        <section class="content-box" style="flex: 1;">
          <h2>Future Projections (SSP Scenarios)</h2>
          <p style="color: var(--text-secondary); margin-bottom: 20px;">Warming trajectories heavily depend on future emissions. Sea level will continue to rise for centuries regardless of pathway.</p>
          <div class="chart-container-wrapper" role="img" aria-label="Line chart showing projected warming under different SSP scenarios by 2100">
            <div class="chart-container">
              <canvas id="sspChart"></canvas>
            </div>
          </div>
        </section>

        <section class="content-box">
          <h2>Mitigation & Adaptation Pathways</h2>
...
    <section class="footer-section animate delay-4">
      <h2>The Narrowing Window for Action</h2>
      <p>The choices made in this decade will determine whether warming can be held to 1.5°C or 2°C. Delayed action locks in high-carbon infrastructure and escalating impacts. Immediate, deep, and sustained emissions reductions are essential to secure a liveable and sustainable future for all.</p>
    </section>

  </main>

  <script>
    // === Menu ===
    function toggleMenu() { 
      var dropdown = document.getElementById('vizMenuDropdown');
      if (dropdown) dropdown.classList.toggle('open'); 
    }
    document.addEventListener('click', function(e) { 
      if (!e.target.closest('.viz-menu')) {
        var dropdown = document.getElementById('vizMenuDropdown');
        if (dropdown) dropdown.classList.remove('open');
      }
    });
    document.addEventListener('keydown', function(e) { 
      if (e.key === 'Escape') {
        var dropdown = document.getElementById('vizMenuDropdown');
        if (dropdown) dropdown.classList.remove('open');
      }
    });

    // === Theme (class-based) ===
    // Enforcing dark theme as default for the poster screenshot but keeping toggle logic for evaluation
    var currentTheme = 'dark';
    function applyTheme(t) {
      document.documentElement.className = 'theme-' + t;
      var themeIcon = document.getElementById('themeIcon');
      var themeLabel = document.getElementById('themeLabel');
      if(themeIcon) themeIcon.textContent = t === 'dark' ? '🌙' : '☀️';
      if(themeLabel) themeLabel.textContent = t === 'dark' ? 'Dark' : 'Light';
      currentTheme = t;
      if (typeof onThemeChange === 'function') onThemeChange();
    }
    function cycleTheme() { applyTheme(currentTheme === 'dark' ? 'light' : 'dark'); }
    applyTheme(currentTheme);

    // === Scroll Reveal ===
    document.querySelectorAll('[data-reveal]').forEach(function(el) { el.classList.add('reveal'); });
    var revealObserver = new IntersectionObserver(function(entries) {
      entries.forEach(function(e) { if (e.isIntersecting) { e.target.classList.add('visible'); revealObserver.unobserve(e.target); } });
    }, { threshold: 0.15 });
    document.querySelectorAll('.reveal').forEach(function(el) { revealObserver.observe(el); });

    // === Number Counter ===
    function animateCounters() {
      document.querySelectorAll('[data-count]').forEach(function(el) {
        if (el.dataset.counted) return;
        el.dataset.counted = '1';
        var target = parseFloat(el.dataset.count), prefix = el.dataset.prefix || '', suffix = el.dataset.suffix || '';
        var start = performance.now(), duration = 1200;
        (function tick(now) {
          var p = Math.min((now - start) / duration, 1), eased = 1 - Math.pow(1 - p, 3);
          // Only animate numbers that are integers properly, or format with 1 decimal if target has decimal
          var isDecimal = target % 1 !== 0;
          var val = isDecimal ? (target * eased).toFixed(1) : Math.round(target * eased);
          el.textContent = prefix + val + suffix;
          if (p < 1) requestAnimationFrame(tick);
          else el.textContent = prefix + target + suffix;
        })(start);
      });
    }
    var counterEl = document.querySelector('[data-count]');
    if (counterEl) {
      var cObs = new IntersectionObserver(function(entries) {
        entries.forEach(function(e) { if (e.isIntersecting) { animateCounters(); cObs.disconnect(); } });
      }, { threshold: 0.3 });
      cObs.observe(counterEl);
    }

    // === Download PNG ===
    async function downloadImage() {
      var menu = document.querySelector('.viz-menu');
      if(menu) menu.style.display = 'none';
      try {
        var url = await htmlToImage.toPng(document.body, { quality: 1, pixelRatio: 2, filter: function(n) { return !n.classList || !n.classList.contains('viz-menu'); } });
        var a = document.createElement('a'); a.href = url;
        a.download = document.title.replace(/\s+/g, '-').toLowerCase() + '.png'; a.click();
      } catch(e) { console.error('Download failed:', e); }
      if(menu) menu.style.display = '';
    }

    // === Chart.js Pattern ===
    var chartsBuilt = false;

    function resetCanvas(id) {
      var old = document.getElementById(id);
      if (!old) return null;
      var parent = old.parentNode;
      var canvas = document.createElement('canvas');
      canvas.id = id;
      parent.replaceChild(canvas, old);
      return canvas;
    }

    function buildCharts() {
      if (chartsBuilt || typeof Chart === 'undefined') return;

      var isDark = document.documentElement.classList.contains('theme-dark');
      var s = getComputedStyle(document.documentElement);
      var textColor = s.getPropertyValue('--text').trim() || (isDark ? '#F8FAFC' : '#020617');
      var gridColor = s.getPropertyValue('--border').trim() || (isDark ? 'rgba(255,255,255,0.08)' : 'rgba(0,0,0,0.1)');

      if (window.myChart) {
        try { window.myChart.destroy(); } catch(e) {}
      }

      var ctx = resetCanvas('sspChart');
      if (ctx) {
        const years = [2020, 2040, 2060, 2080, 2100];
        window.myChart = new Chart(ctx.getContext('2d'), {
          type: 'line',
          data: {
            labels: years,
            datasets: [
              { label: 'SSP5-8.5 (~4.4°C)', data: [1.1, 1.8, 2.7, 3.6, 4.4], borderColor: '#991B1B', backgroundColor: '#991B1B', borderWidth: 6, pointRadius: 6, tension: 0.3 },
              { label: 'SSP3-7.0 (~3.6°C)', data: [1.1, 1.6, 2.3, 3.0, 3.6], borderColor: '#DC2626', backgroundColor: '#DC2626', borderWidth: 5, pointRadius: 5, tension: 0.3 },
              { label: 'SSP2-4.5 (~2.7°C)', data: [1.1, 1.5, 2.0, 2.4, 2.7], borderColor: '#F59E0B', backgroundColor: '#F59E0B', borderWidth: 5, pointRadius: 5, tension: 0.3 },
              { label: 'SSP1-2.6 (~1.8°C)', data: [1.1, 1.4, 1.7, 1.8, 1.8], borderColor: '#38BDF8', backgroundColor: '#38BDF8', borderWidth: 5, pointRadius: 5, tension: 0.3 },
              { label: 'SSP1-1.9 (~1.4°C)', data: [1.1, 1.5, 1.4, 1.4, 1.4], borderColor: '#10B981', backgroundColor: '#10B981', borderWidth: 6, pointRadius: 6, tension: 0.3 }
            ]
          },
          options: {
            responsive: true,
            maintainAspectRatio: false,
            plugins: {
              tooltip: { enabled: true, titleFont: { size: 24 }, bodyFont: { size: 24 }, padding: 16 },
              legend: { position: 'top', labels: { color: textColor, font: { family: 'Inter', size: 24, weight: '500' }, padding: 30, usePointStyle: true, pointStyle: 'circle' } }
            },
            scales: {
              x: { ticks: { color: textColor, font: { size: 24 } }, grid: { color: gridColor, drawBorder: false } },
              y: { title: { display: true, text: 'Global Warming (°C)', color: textColor, font: { size: 24, weight: '500' } }, ticks: { color: textColor, font: { size: 24 } }, grid: { color: gridColor, drawBorder: false }, min: 1.0, max: 5.0 }
            },
            layout: { padding: 20 }
          }
        });
      }

      chartsBuilt = true;
    }

    function onThemeChange() {
      chartsBuilt = false;
      setTimeout(buildCharts, 100);
    }

    document.addEventListener('DOMContentLoaded', buildCharts);
  </script>
</body>
</html>
